// Type-safe wrapper over Tauri's `invoke()` for the DeepCode renderer.
// Replaces the previous Electron contextBridge surface (window.deepcode.*).
//
// Each function maps to a #[tauri::command] in apps/desktop/src-tauri/src/commands.rs.

import { invoke } from '@tauri-apps/api/core';

export interface AppInfo {
  version: string;
  platform: string;
  home_dir: string | null;
}

export interface Credentials {
  apiKey?: string;
  authToken?: string;
  baseURL?: string;
}

export interface AppServerStatus {
  running: boolean;
  pid?: number;
}

export interface SessionMeta {
  id: string;
  path: string;
  size_bytes: number;
  updated_at_secs: number;
  /** Auto-derived from the first user message (falls back to the id). */
  title: string;
}

export async function getAppInfo(): Promise<AppInfo> {
  return invoke('get_app_info');
}

export async function appServerStart(): Promise<AppServerStatus> {
  return invoke('app_server_start');
}

export async function appServerSend(message: string): Promise<void> {
  await invoke('app_server_send', { message });
}

export async function appServerStop(): Promise<void> {
  await invoke('app_server_stop');
}

export async function appServerStatus(): Promise<AppServerStatus> {
  return invoke('app_server_status');
}

export async function credentialStatus(): Promise<{ hasKey: boolean; baseURL?: string }> {
  const raw = (await invoke('credential_status')) as { hasKey: boolean; baseUrl?: string };
  return { hasKey: raw.hasKey, baseURL: raw.baseUrl };
}

export async function saveCredentials(creds: Credentials): Promise<void> {
  await invoke('save_credentials', {
    creds: {
      api_key: creds.apiKey,
      auth_token: creds.authToken,
      base_url: creds.baseURL,
    },
  });
}

export async function loadSettingsFile(): Promise<Record<string, unknown>> {
  return (await invoke('load_settings_file')) as Record<string, unknown>;
}

export async function saveSettingsFile(value: Record<string, unknown>): Promise<void> {
  await invoke('save_settings_file', { value });
}

export async function getSettingsPath(): Promise<string | null> {
  return (await invoke('get_settings_path')) as string | null;
}

/** Append a permissions matcher to ~/.deepcode/settings.json. Idempotent. */
export async function appendAllowMatcher(matcher: string): Promise<void> {
  await invoke('append_allow_matcher', { matcher });
}

export interface KeybindingsConfigOnDisk {
  enabled?: boolean;
  vim?: boolean;
  bindings?: Array<{
    key: string;
    action: string;
    when?: 'NORMAL' | 'INSERT' | 'VISUAL';
    description?: string;
  }>;
}

/** Read ~/.deepcode/keybindings.json. Returns {} if absent. */
export async function loadKeybindings(): Promise<KeybindingsConfigOnDisk> {
  return (await invoke('load_keybindings')) as KeybindingsConfigOnDisk;
}

/** Write ~/.deepcode/keybindings.json. */
export async function saveKeybindings(value: KeybindingsConfigOnDisk): Promise<void> {
  await invoke('save_keybindings', { value });
}

/** Show native folder-picker dialog. Returns absolute path or null on cancel. */
export async function pickFolder(): Promise<string | null> {
  const { open } = await import('@tauri-apps/plugin-dialog');
  const result: unknown = await open({
    multiple: false,
    directory: true,
    title: 'Choose a project folder for DeepCode',
  });
  if (typeof result === 'string') return result;
  if (Array.isArray(result) && result.length > 0 && typeof result[0] === 'string') {
    return result[0];
  }
  return null;
}

/** Show native file-picker dialog (single file). Returns absolute path or null on cancel. */
export async function pickFile(opts: { defaultPath?: string } = {}): Promise<string | null> {
  const { open } = await import('@tauri-apps/plugin-dialog');
  const result: unknown = await open({
    multiple: false,
    directory: false,
    title: 'Attach a file',
    defaultPath: opts.defaultPath,
  });
  if (typeof result === 'string') return result;
  if (Array.isArray(result) && result.length > 0 && typeof result[0] === 'string') {
    return result[0];
  }
  return null;
}

export async function listSessions(): Promise<SessionMeta[]> {
  return (await invoke('list_sessions')) as SessionMeta[];
}

/** A plugin row as returned by the `list_plugins` Rust command (camelCase). */
export interface PluginInfo {
  name: string;
  version: string;
  enabled: boolean;
  contributedHookEvents: string[];
  sourceHash: string;
  trustedBy: 'user' | 'marketplace' | 'official';
  warning?: string;
}

/** Installed plugins from ~/.deepcode/plugins (reads plugin.json + trust). */
export async function listPlugins(): Promise<PluginInfo[]> {
  return (await invoke('list_plugins')) as PluginInfo[];
}

/** A skill row as returned by the `list_skills` Rust command (camelCase). */
export interface SkillInfo {
  name: string;
  description: string;
  source: 'builtin' | 'user' | 'project' | 'plugin';
  path: string;
  body: string;
}

/** Built-in (bundled) + user + project skills. `cwd` enables project skills. */
export async function listSkills(cwd?: string): Promise<SkillInfo[]> {
  return (await invoke('list_skills', { cwd })) as SkillInfo[];
}

/** Set (or clear, with '') a session's manual title. */
export async function sessionSetTitle(id: string, title: string): Promise<void> {
  await invoke('session_set_title', { id, title });
}

/** Permanently delete a session's JSONL file. */
export async function sessionDelete(id: string): Promise<void> {
  await invoke('session_delete', { id });
}

/** Archive a session (moved to sessions/archived/, hidden from the list). */
export async function sessionArchive(id: string): Promise<void> {
  await invoke('session_archive', { id });
}

/** A stored message line as written to a session's JSONL. */
export interface StoredMessageLine {
  type?: string;
  role: 'user' | 'assistant';
  content: Array<Record<string, unknown>>;
  timestamp?: string;
}

/** Read a session's message lines (meta header + unparseable lines skipped). */
export async function sessionRead(id: string): Promise<StoredMessageLine[]> {
  return (await invoke('session_read', { id })) as StoredMessageLine[];
}

export async function cliPath(): Promise<string | null> {
  return (await invoke('cli_path')) as string | null;
}

/**
 * Read a file's text via the unscoped `tool_read` Rust command (the file panel's
 * Source view). Returns up to the first 2000 lines (tool_read's default limit).
 */
export async function toolRead(filePath: string): Promise<string> {
  const r = (await invoke('tool_read', { filePath })) as { content: string };
  return r.content;
}

/** Open a URL in the user's default browser. */
export async function openUrl(url: string): Promise<void> {
  const { openUrl: openerOpen } = await import('@tauri-apps/plugin-opener');
  await openerOpen(url);
}

/** One file snapshot from a session — the `session_snapshots` command's row. */
export interface SessionSnapshot {
  /** Sequence within the session (ascending = chronological). */
  seq: number;
  /** Capture time, unix ms. */
  capturedAtMs: number;
  /** "pre-Edit" / "post-Write" / … */
  reason: string;
  /** sha256[:16] of the blob (used to collapse duplicate states). */
  hash: string;
  /** The captured file contents. */
  content: string;
}

/**
 * List a file's session snapshots for the Diff/History tabs. Returns the rows
 * seq-ascending; an empty array when the session has none (file untouched).
 */
export async function sessionSnapshots(
  sessionId: string,
  filePath: string,
): Promise<SessionSnapshot[]> {
  return (await invoke('session_snapshots', { sessionId, filePath })) as SessionSnapshot[];
}
